// middleware/requirePlayer.js
//
// Resolves the authenticated user to an internal player record.
// Must run after jwtCheck (express-oauth2-jwt-bearer) so that req.auth is populated.
//
// Flow:
//   1. Extract the player_id UUID from the custom JWT claim.
//   2. Check in-memory cache for the player record.
//   3. If not cached, look up or lazy-provision the player row in the DB.
//   4. Attach the player record to req.player for downstream controllers.
//
// The player_id in the token is generated by Auth0's Post-Registration Action
// and stored in app_metadata (server-controlled, not user-editable).
// See AUTH0_SETUP.md for the Action code.

const { query } = require('../config/database');
const logger = require('../config/logger');

const PLAYER_ID_CLAIM = 'https://bowling-tournament-api.com/player_id';
const PLAYER_EMAIL_CLAIM = 'https://bowling-tournament-api.com/player_email';
const PLAYER_NAME_CLAIM = 'https://bowling-tournament-api.com/player_name';

// Simple in-memory cache: playerId → { player, expiresAt }
// TTL keeps it fresh without hitting the DB on every request.
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
const playerCache = new Map();

const requirePlayer = async (req, res, next) => {
  try {
    const playerId = req.auth?.payload?.[PLAYER_ID_CLAIM];
    const playerEmail = req.auth?.payload?.[PLAYER_EMAIL_CLAIM];
    const playerName = req.auth?.payload?.[PLAYER_NAME_CLAIM];

    if (!playerId) {
      return res.status(403).json({
        error: 'Token is missing the player identity claim. '
          + 'Ensure the Auth0 Post-Login Action is deployed and the user '
          + 'has app_metadata.player_id set.',
      });
    }

    // Check cache
    const cached = playerCache.get(playerId);
    if (cached && cached.expiresAt > Date.now()) {
      req.player = cached.player;
      return next();
    }

    // Cache miss — upsert (lazy provision on first login, SELECT on subsequent).
    // If the player was created via invite flow (status='invited'), activate them.
    const result = await query(
      `INSERT INTO players (id, name, email, status)
       VALUES ($1, $2, $3, 'active')
       ON CONFLICT (id) DO UPDATE
         SET updated_at = CURRENT_TIMESTAMP,
             status = CASE WHEN players.status = 'invited' THEN 'active' ELSE players.status END
       RETURNING *`,
      [playerId, playerName, playerEmail],
    );

    const player = result.rows[0];
    playerCache.set(playerId, { player, expiresAt: Date.now() + CACHE_TTL_MS });

    req.player = player;
    next();
  } catch (error) {
    logger.error({ err: error, message: error.message, stack: error.stack }, 'requirePlayer: failed to resolve player identity');
    res.status(500).json({ error: 'Failed to resolve player identity' });
  }
};

module.exports = requirePlayer;
